import {FIELD_CASES,FIELD_QUANTITIES,FIELD_UNITS,fieldExample} from './field-notebook-content.mjs';
import {fieldNotebook,currentFieldCase,fieldDraftSnapshot,currentFieldChecks,fieldCurrentTask,fieldSourceRows,chooseFieldCase,nextFieldCase,setFieldPage,setFieldReadPrompt,setFieldSourceDay,toggleFieldRow,setFieldQuantity,setFieldUnit,setFieldValue,setFieldBarInput,setFieldModelInput,useFieldSupport,checkFieldData,checkFieldChart,answerFieldDraft,answerFieldSource,answerFieldModel,keepFieldDraft,recoverFieldNotebook} from './field-notebook-core.mjs';
import {plantStudy} from './plant-study-core.mjs';
import {PLANT_MODEL,PLANT_DAYS,plantObservationById} from './plant-study-content.mjs';
import {fieldChartArt} from './field-notebook-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=[['data','Data'],['chart','Build'],['read','Read & check'],['keep','Keep or revise']];
const toggle=(attr,id,label,on=false)=>`<button type="button" class="secondary ${on?'selected':''}" data-fn-${attr}="${id}" aria-pressed="${on}">${label}</button>`;
const rowName=r=>`Day ${r.day} · ${r.conditionLabel} · ${r.specimen}`;
const notice=()=>`<p class="fn-notice">${esc(PLANT_MODEL.notice)}</p>`;
function rowTable(rows,{origins=false,remove=false}={}){if(!rows.length)return '<p>No source rows chosen yet. Choose up to two on the Data page.</p>';return `<div class="fn-source-rows">${rows.map(item=>{const r=item.observation||item;return `<div class="fn-source-row"><span><strong>${esc(rowName(r))}</strong><small>${origins?(item.origin==='kept-in-plant-study'?'Previously kept in Plant Study':'Supplied model row'):''}</small></span><span class="fn-mm">${r.stemMm}<small>stem mm</small></span>${remove?`<button type="button" class="text-button" data-fn-row="${r.id}" aria-label="Remove ${esc(rowName(r))}">Remove</button>`:''}</div>`;}).join('')}</div>`;}
const sameDraft=(a,b)=>JSON.stringify([a.caseId,a.rows,a.values,a.quantity,a.unit])===JSON.stringify([b.caseId,b.rows,b.values,b.quantity,b.unit]);
function feedback(state,task){const c=currentFieldChecks(state)[task];if(!c)return '';if(!sameDraft(c.snapshot,fieldDraftSnapshot(state)))return '<p class="fn-feedback tiny">An earlier check is kept in your notes. Check this draft when you want feedback on the changes.</p>';let parts=[];if(task==='data')parts=[c.result.feedback];else if(task==='chart')parts=[c.result.data.feedback,c.result.quantity.feedback,c.result.unit.feedback,...c.result.bars.map(b=>b.feedback)];else parts=[c.result.feedback];return `<section class="fn-feedback" id="fn-feedback" tabindex="-1" role="status"><strong>This check of your draft</strong>${parts.map(p=>`<p>${esc(p)}</p>`).join('')}<p class="tiny">Visible-source practice${c.familiar?' · familiar work':''}. Earlier help stays with this check.</p></section>`;}
function packet(state,s,w){const kept=plantStudy(state)?.observations||[];return `<section class="fn-packet"><h3>Supplied model table</h3><p>Stem lengths in millimeters. Browse a day; choose rows that answer your question.</p><div class="fn-controls" role="group" aria-label="Source model day">${PLANT_DAYS.map(d=>toggle('day',d,`Day ${d}`,s.sourceDay===d)).join('')}</div><div class="fn-packet-rows">${fieldSourceRows(s.sourceDay).map(r=>{const selected=w.rows.some(x=>x.observation.id===r.id);return `<button type="button" class="fn-row-choice ${selected?'selected':''}" data-fn-row="${r.id}" aria-pressed="${selected}"><span><strong>${esc(r.conditionLabel)} · ${r.specimen}</strong><small>Day ${r.day}${kept.includes(r.id)?' · kept in Plant Study':' · supplied model row'}</small></span><span>${r.stemMm}<small>stem mm</small></span></button>`;}).join('')}</div><p id="fn-selection-status" role="status" class="tiny">${w.rows.length} of 2 rows selected. Remove a row to make room for another.</p><details><summary>Leaf clues, controls and sources</summary>${fieldSourceRows(s.sourceDay).map(r=>`<p><strong>${r.conditionLabel} ${r.specimen}:</strong> ${esc(r.description)}</p>`).join('')}<p>${esc(PLANT_MODEL.controls)}</p><ul>${PLANT_MODEL.sources.map(x=>`<li><a href="${x.url}" target="_blank" rel="noopener">${esc(x.title)}</a></li>`).join('')}</ul></details></section>`;}
function sourceStrip(w){return `<section class="fn-canonical"><h3>Selected source rows · stem mm</h3>${rowTable(w.rows,{origins:true,remove:true})}<p class="tiny">These source numbers stay unchanged when you edit your chart.</p></section>`;}
function barControls(w){return `<div class="fn-label-pickers"><label>What quantity does your chart show?<select data-fn-quantity><option value="">Choose a quantity</option>${FIELD_QUANTITIES.map(q=>`<option value="${q.id}" ${w.quantity===q.id?'selected':''}>${q.label}</option>`).join('')}</select></label><label>What unit labels your entries?<select data-fn-unit><option value="">Choose a unit</option>${FIELD_UNITS.map(q=>`<option value="${q.id}" ${w.unit===q.id?'selected':''}>${q.label}</option>`).join('')}</select></label></div>${w.rows.map(({observation:r})=>`<form class="fn-bar-editor" data-fn-value-form="${r.id}" novalidate><label for="fn-value-${r.id}">${esc(rowName(r))}</label><div class="fn-number-row"><input id="fn-value-${r.id}" name="value" type="text" inputmode="numeric" autocomplete="off" value="${esc(w.pending.bars[r.id])}" maxlength="16" placeholder="Blank" aria-describedby="fn-value-error-${r.id}"><button type="submit" class="secondary">Set bar</button><button type="button" class="text-button" data-fn-clear="${r.id}">Clear</button></div><div class="fn-controls" aria-label="Adjust ${esc(rowName(r))}">${[-10,-1,1,10].map(n=>`<button type="button" class="secondary" data-fn-adjust="${r.id}:${n}" aria-label="${n<0?'Subtract':'Add'} ${Math.abs(n)} ${n<0?'from':'to'} ${esc(rowName(r))}">${n>0?'+':''}${n}</button>`).join('')}</div><span class="tiny" role="status" id="fn-value-error-${r.id}"></span></form>`).join('')}`;}
function readTask(state,s,x){const task=s.readPrompt,draft=fieldDraftSnapshot(state),w=x.work,last=currentFieldChecks(state)[task],response=last&&sameDraft(last.snapshot,draft)?last.response:null;let content='';if(task==='draft')content=`<h3>Read the chart you made</h3><p>Which of your two numerical bars is longer? Read your entries, even if they differ from the source.</p><div class="fn-choices">${[['first','The first bar is longer'],['second','The second bar is longer'],['same','The bars have the same length']].map(([id,label])=>toggle('draft',id,label,response===id)).join('')}</div><p class="tiny">Both bars need an entered value to compare them. Blank is different from zero.</p>`;else if(task==='source')content=`<h3>Does your chart match its source rows?</h3><p>Do both numerical bars, the quantity label and the unit agree with the supplied table?</p><div class="fn-choices">${[['yes','Yes, they agree'],['differs','Something differs or is missing'],['unsure','I’m not sure yet']].map(([id,label])=>toggle('source',id,label,response===id)).join('')}</div><p class="tiny">Matching your chosen rows is separate from choosing the rows this question needs.</p>`;else content=`<h3>Answer the original question from the model table</h3><p>${esc(x.definition.question)}</p><div class="fn-requested"><strong>Supplied requested pair</strong>${rowTable(x.definition.targetIds.map(plantObservationById))}</div><form id="fn-model-form" novalidate><fieldset><legend>Which requested stem length is greater?</legend><label><input type="radio" name="comparison" value="light" ${w.pending.modelChoice==='light'?'checked':''}> Adequate-light is longer</label><label><input type="radio" name="comparison" value="dim" ${w.pending.modelChoice==='dim'?'checked':''}> Too-little-light is longer</label><label><input type="radio" name="comparison" value="same" ${w.pending.modelChoice==='same'?'checked':''}> They are the same length</label><label><input type="radio" name="comparison" value="unsure" ${w.pending.modelChoice==='unsure'?'checked':''}> I’m not sure yet</label></fieldset><label for="fn-difference">Optional: how many millimeters apart are they?<input id="fn-difference" name="difference" type="text" inputmode="numeric" autocomplete="off" maxlength="16" value="${esc(w.pending.difference)}" placeholder="Leave blank if you like"></label><button type="submit" class="primary">Compare with the model table</button><p id="fn-model-error" role="status"></p></form>`;
 const mobile=`<div class="fn-mobile-chart">${fieldChartArt(draft)}${w.rows.length?`<h4>Supplied source rows · stem mm</h4>${rowTable(w.rows)}`:''}</div>`;content=content.replace('</p>','</p>'+mobile);
 return `<div class="fn-read-tabs" aria-label="Reading questions">${[['draft','My chart'],['source','Source check'],['model','Model question']].map(([id,label])=>toggle('read',id,label,task===id)).join('')}</div>${content}${feedback(state,task)}<p id="fn-read-status" role="status"></p>`;
}
function keptContent(kept){return `${fieldChartArt(kept.draft)}<details><summary>Source rows and labels kept with this draft</summary>${rowTable(kept.draft.rows,{origins:true})}${notice()}</details><p class="tiny">${kept.revised?'A revised kept draft.':'A first kept draft.'} Help and earlier checks travel with it; keeping is not a pass.</p>`;}
function task(state,s,x){if(s.page==='data')return `<h2 id="fn-title" tabindex="-1">Which observations answer this question?</h2>${packet(state,s,x.work)}<h3>Your selected pair</h3>${rowTable(x.work.rows,{origins:true,remove:true})}<button type="button" class="primary" data-fn-check="data">Check my data</button>${feedback(state,'data')}<p><button type="button" class="secondary" data-fn-page="chart">Build a chart with these rows →</button></p>`;if(s.page==='chart')return `<h2 id="fn-title" tabindex="-1">Make the numbers visible</h2><p>Copy each selected stem length in mm into a bar. Set a bar to update the picture, or apply both entries when you check. Choose its quantity and unit labels. A blank is waiting for a value; zero is a value.</p>${barControls(x.work)}<button type="button" class="primary" data-fn-check="chart">Apply entries and check my chart</button><p id="fn-chart-error" role="status"></p>${feedback(state,'chart')}<p><button type="button" class="secondary" data-fn-page="read">Read and question the draft →</button></p>`;if(s.page==='read')return `<h2 id="fn-title" tabindex="-1">What does this chart say?</h2>${readTask(state,s,x)}`;return `<h2 id="fn-title" tabindex="-1">Something to keep or change?</h2><p>A draft can hold a question or an unfinished idea. Keep it as it is, or change the rows, labels and bars.</p><button type="button" class="primary" data-fn-keep>Keep this draft</button><p><button type="button" class="secondary" data-fn-page="chart">Revise my chart</button></p>${x.work.kept?`<section class="fn-kept" id="fn-kept" tabindex="-1"><h3>Your kept draft for this question</h3>${keptContent(x.work.kept)}</section>`:''}<p>Tell someone: “I chose these rows because…” or “I would change…” There is no score for your explanation.</p><a class="secondary" href="#regrow">Visit the planting corner</a>`;}
function support(state,s,x){const t=fieldCurrentTask(state),flags=x.work.support[t]||{},example=flags.example?fieldExample(x.definition.id):null,say=t==='draft'?'Read the chart you made. Which of your two numerical bars is longer? Read your entries, even if they differ from the source.':t==='source'?'Do both numerical bars, the quantity label and the unit agree with the supplied table? Matching your chosen rows is separate from choosing the rows this question needs.':t==='chart'?'Copy each selected stem length in millimeters into a bar. Choose the quantity and unit labels. Set a bar to update the picture, or apply both entries when you check. Blank is different from zero.':t==='keep'?'You can keep an unfinished draft or change its rows, labels and bars. There is no score for your explanation.':x.definition.question;return `<aside class="fn-support"><div class="fn-controls"><button type="button" class="secondary" data-fn-support="help">A useful clue</button><button type="button" class="secondary" data-fn-support="example">A different example</button><button type="button" class="secondary" data-fn-support="together" aria-pressed="${!!flags.together}">${flags.together?'Working together is kept':'We’re working together'}</button><span data-fn-audio>${hearButton(say,'Hear this turn')}</span></div>${flags.help?'<p>Find the requested day and specimen first. Compare one row for each light condition. For the chart, match each numerical entry and its labels to the supplied stem-mm table. Reading your own draft and checking its source are different jobs.</p>':''}${example?`<section class="fn-example"><h3>A supplied, different-case example</h3><p>${esc(example.definition.question)}</p>${rowTable(example.rows)}<p>These two rows share a day and a specimen. Label their bars “stem length” and “mm,” then enter each supplied length. ${example.definition.longer==='same'?'The bars would be equal.':'The too-little-light bar would be longer.'} This example does not change your rows or bars.</p></section>`:''}</aside>`;}
export function fieldNotebookEntry(){return '<aside class="fn-entry"><div><h2>What could your observations tell us?</h2><p>Choose useful data, build a chart, then question and revise it.</p></div><a class="secondary" href="#living/notebook">Open the Field Notebook →</a></aside>';}
export function fieldNotebookPage(state){const s=fieldNotebook(state);if(!s)return '<section class="panel"><h1 id="fn-title" tabindex="-1">An earlier Field Notebook is kept</h1><p>This format cannot be opened. Its exact record stays in notes downloads.</p><button type="button" class="secondary" data-fn-recover>Keep the earlier record and start fresh</button></section>';const x=currentFieldCase(state),draft=fieldDraftSnapshot(state);return `<div class="fn-workspace fn-page-${s.page}"><header><a class="back" href="#living">← Living Garden</a><h1>The Field Notebook</h1><p>Help rebuild the growing shelf with an observation we can explain.</p></header><section class="fn-request"><strong>Our question · day ${x.definition.day}, specimen ${x.definition.specimen}</strong><p>${esc(x.definition.question)}</p>${x.work.familiar?'<span class="tiny">A familiar comparison to revisit.</span>':''}</section><nav class="fn-steps" aria-label="Field Notebook task">${pages.map(([id,label],i)=>toggle('page',id,`${i+1}. ${label}`,s.page===id)).join('')}</nav>${notice()}<div class="fn-layout"><section class="fn-task">${task(state,s,x)}</section>${s.page==='data'?'':`<aside class="fn-reference">${fieldChartArt(draft)}${sourceStrip(x.work)}</aside>`}</div>${support(state,s,x)}<details class="fn-cases"><summary>Choose any of eight comparisons</summary><div class="fn-case-grid">${FIELD_CASES.map(c=>toggle('case',c.id,`Day ${c.day} · specimen ${c.specimen}`,c.id===s.currentCase)).join('')}</div><p>Eight authored comparisons return as familiar practice. They are not generated stories or real growth measurements.</p></details><div class="fn-footer"><button type="button" class="secondary" data-fn-next>Another comparison</button><a href="#living/plants">Back to the seedlings</a><a href="#living">Take a break</a><a href="#notes">Grown-up notes</a></div></div>`;}
export function fieldNotebookPlanPanel(state){const s=fieldNotebook(state),x=s&&currentFieldCase(state);if(!x?.work.kept)return '';return `<aside class="fn-entry fn-planting" tabindex="-1"><div><h2>A chart for the growing shelf</h2><p>${esc(x.definition.question)}</p>${notice()}${keptContent(x.work.kept)}<a class="secondary" href="#living/notebook">Return to this notebook question</a></div></aside>`;}
export function bindFieldNotebook(state,ctx){const refresh=(target='#fn-title')=>{ctx.save();ctx.render();ctx.focus?.(target);};const act=(fn,target)=>{if(fn())refresh(target);};const task=()=>fieldCurrentTask(state);document.querySelectorAll('[data-fn-page]').forEach(b=>b.onclick=()=>act(()=>setFieldPage(state,b.dataset.fnPage)));document.querySelectorAll('[data-fn-read]').forEach(b=>b.onclick=()=>act(()=>setFieldReadPrompt(state,b.dataset.fnRead)));document.querySelectorAll('[data-fn-day]').forEach(b=>b.onclick=()=>act(()=>setFieldSourceDay(state,Number(b.dataset.fnDay)),`[data-fn-day="${b.dataset.fnDay}"]`));document.querySelectorAll('[data-fn-case]').forEach(b=>b.onclick=()=>{if(chooseFieldCase(state,b.dataset.fnCase)){setFieldPage(state,'data');setFieldSourceDay(state,currentFieldCase(state).definition.day);refresh();}});document.querySelector('[data-fn-next]')?.addEventListener('click',()=>{if(nextFieldCase(state)){setFieldPage(state,'data');setFieldSourceDay(state,currentFieldCase(state).definition.day);refresh();}});document.querySelectorAll('[data-fn-row]').forEach(b=>b.onclick=()=>{const id=b.dataset.fnRow,origin=plantStudy(state)?.observations.includes(id)?'kept-in-plant-study':'supplied-model';if(toggleFieldRow(state,id,origin))refresh('#fn-title');else{const status=document.querySelector('#fn-selection-status');if(status)status.textContent='Two rows are already selected. Remove one to choose another.';}});document.querySelector('[data-fn-quantity]')?.addEventListener('change',e=>act(()=>setFieldQuantity(state,e.target.value||null),'[data-fn-quantity]'));document.querySelector('[data-fn-unit]')?.addEventListener('change',e=>act(()=>setFieldUnit(state,e.target.value||null),'[data-fn-unit]'));document.querySelectorAll('[data-fn-value-form] input[name=value]').forEach(input=>input.addEventListener('input',()=>{if(setFieldBarInput(state,input.closest('form').dataset.fnValueForm,input.value)){ctx.save();const draft=fieldDraftSnapshot(state);document.querySelectorAll('.fn-pending-notice').forEach(el=>el.hidden=!draft.rows.some(({observation:r})=>draft.pending.bars[r.id]!==String(draft.values[r.id]??'')));}}));document.querySelectorAll('#fn-model-form input[name=comparison]').forEach(input=>input.addEventListener('change',()=>{setFieldModelInput(state,'choice',input.value);ctx.save();}));document.querySelector('#fn-difference')?.addEventListener('input',e=>{setFieldModelInput(state,'difference',e.target.value);ctx.save();});document.querySelectorAll('[data-fn-value-form]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const raw=form.elements.value.value.trim(),id=form.dataset.fnValueForm;if(!/^(?:0|[1-9]\d?)$/.test(raw)||Number(raw)>70){document.querySelector(`#fn-value-error-${id}`).textContent='Enter a whole number from 0 to 70, or use Clear to leave this bar blank.';return;}act(()=>setFieldValue(state,id,Number(raw)),`#fn-value-${id}`);}));document.querySelectorAll('[data-fn-clear]').forEach(b=>b.onclick=()=>act(()=>setFieldValue(state,b.dataset.fnClear,null),`#fn-value-${b.dataset.fnClear}`));document.querySelectorAll('[data-fn-adjust]').forEach(b=>b.onclick=()=>{const [id,delta]=b.dataset.fnAdjust.split(':'),raw=currentFieldCase(state).work.pending.bars[id].trim();if(raw!==''&&(!/^(?:0|[1-9]\d?)$/.test(raw)||Number(raw)>70)){document.querySelector(`#fn-value-error-${id}`).textContent='Edit this entry to a whole number from 0 to 70, or Clear it, before adjusting. Your text is still here.';return;}if(raw===''&&Number(delta)<0)return;const value=raw===''?0:Number(raw);act(()=>setFieldValue(state,id,Math.max(0,Math.min(70,value+Number(delta)))),`#fn-value-${id}`);});document.querySelectorAll('[data-fn-check]').forEach(b=>b.onclick=()=>{if(b.dataset.fnCheck==='chart'){const w=currentFieldCase(state).work;for(const {observation:r} of w.rows){const raw=w.pending.bars[r.id].trim();if(raw!==''&&(!/^(?:0|[1-9]\d?)$/.test(raw)||Number(raw)>70)){document.querySelector('#fn-chart-error').textContent='One entry is not a whole number from 0 to 70. Edit it, or Clear it to leave a blank. Your entries are still here.';return;}}for(const {observation:r} of w.rows){const raw=w.pending.bars[r.id].trim();setFieldValue(state,r.id,raw===''?null:Number(raw));}}act(()=>b.dataset.fnCheck==='data'?checkFieldData(state):checkFieldChart(state),'#fn-feedback');});document.querySelectorAll('[data-fn-draft]').forEach(b=>b.onclick=()=>{if(answerFieldDraft(state,b.dataset.fnDraft))refresh('#fn-feedback');else document.querySelector('#fn-read-status').textContent='Enter both numerical bar values on Build first. Blank is not zero.';});document.querySelectorAll('[data-fn-source]').forEach(b=>b.onclick=()=>act(()=>answerFieldSource(state,b.dataset.fnSource),'#fn-feedback'));document.querySelector('#fn-model-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,choice=form.elements.comparison.value,raw=form.elements.difference.value.trim();if(!choice||raw!==''&&(!/^(?:0|[1-9]\d?)$/.test(raw)||Number(raw)>70)){document.querySelector('#fn-model-error').textContent='Choose a comparison. Leave the difference blank, or enter a whole number from 0 to 70.';return;}act(()=>answerFieldModel(state,choice,raw===''?null:Number(raw)),'#fn-feedback');});document.querySelectorAll('[data-fn-support]').forEach(b=>b.onclick=()=>act(()=>useFieldSupport(state,task(),b.dataset.fnSupport),'.fn-support'));document.querySelectorAll('[data-fn-audio] [data-speak]').forEach(b=>b.addEventListener('click',()=>{useFieldSupport(state,task(),'audio');ctx.save();}));document.querySelector('[data-fn-keep]')?.addEventListener('click',()=>act(()=>keepFieldDraft(state),'#fn-kept'));document.querySelector('[data-fn-recover]')?.addEventListener('click',()=>act(()=>recoverFieldNotebook(state)));}
export function fieldNotebookNotes(state){if(!Object.hasOwn(state,'fieldNotebook'))return '';return `<details class="panel" data-fn-notes><summary>Field Notebook: data, chart and revision</summary><p>Invented source data. Selecting relevant rows, copying values and labels, reading a draft and answering from a source are separate visible-source practice. Checks and kept drafts freeze the source, entries and help at that time. No independent measurement, learning level or real plant conclusion is inferred.</p><pre>${esc(JSON.stringify(state.fieldNotebook,null,2))}</pre></details>`;}
